Snippet (range clamping):

const { retentionDays, policyId } = await retention.getAuditLogRetention({ tenantId, env });
const cutoff = retention.cutoffFromDays(retentionDays, now);

if (requestedEnd <= cutoff) {
  throw new HttpError(422, `Requested range is entirely outside retention window (cutoff=${cutoff.toISOString()}).`);
}

const effectiveStart = requestedStart < cutoff ? cutoff : requestedStart;
const warnings = [];
if (requestedStart < cutoff) {
  warnings.push({ code: 'RETENTION_CLAMPED_START', message: 'Requested start was before retention cutoff; export was clamped.' });
}

// Query uses effectiveStart
const rows = await auditLogStore.query({ start: effectiveStart, end: requestedEnd, ... });

